    def upload_file(input: UploadFileInput) -> Any:
        resolved_name = input.display_name or os.path.basename(input.file_path)
        with open(input.file_path, "rb") as handle:
            uploaded = _upload_file(
                client,
                handle,
                display_name=resolved_name,
                **drop_none({"type": input.type}),
            )
        return to_dict(uploaded)

